import os, json

BASE_DIR = 'storage/noesis/nmap'
SUMMARY_PATH = os.path.join(BASE_DIR, 'appendix_E_summary.json')
PROM_CMP = os.path.join(BASE_DIR, 'prometheus_620_sets_compare.json')        # Eval 658
PROM_X  = os.path.join(BASE_DIR, 'prometheus_620_crossing_examples.json')    # Eval 660
SENS    = os.path.join(BASE_DIR, 'gate_sensitivity_v1_noesis.json')          # Eval 656

def load_json(path):
    if not os.path.exists(path):
        return None
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception:
        return None

def save_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        json.dump(obj, f, indent=2)

def construct_packing():
    # Load existing summary (if any)
    summary = load_json(SUMMARY_PATH) or {
        "version": "v1",
        "notes": "Sets-only Appendix E summary. All entries cite Eval IDs and storage paths."
    }

    # Load inputs
    cmp_data = load_json(PROM_CMP)
    x_data   = load_json(PROM_X)
    sens     = load_json(SENS)

    # Merge Prometheus_620 compare
    if cmp_data:
        prom_entry = {
            "eval_compare": 658,
            "files": cmp_data.get("files", {}),
            "boundary_2e8": cmp_data.get("boundary_2e8", {}),
            "topk_rank_based": cmp_data.get("topk_rank_based", {}),
            "gate_v1_noesis_geometry": cmp_data.get("gate_v1_noesis_geometry", {})
        }
        summary["prometheus_620"] = prom_entry

    # Merge Prometheus_620 crossing
    if x_data:
        cross_entry = {
            "eval_crossing": 660,
            "dual_intersection_size": x_data.get("dual_intersection_size"),
            "dual_interior_size@1e-8": x_data.get("dual_interior_size@1e-8"),
            "motif_count": len(x_data.get("crossing_motifs", [])),
            "motifs_path": PROM_X
        }
        summary["prometheus_620_crossing"] = cross_entry

    # Merge Gate v1 sensitivity
    if sens:
        sens_entry = {
            "eval": 656,
            "results": sens.get("gate_v1_sensitivity", []),
            "path": SENS
        }
        summary["noesis_gate_v1_sensitivity"] = sens_entry

    save_json(SUMMARY_PATH, summary)

    # Return a valid packing (baseline snapshot with tiny final shrink)
    import numpy as np
    SNAP_C = 'storage/noesis/latest_centers.txt'
    SNAP_R = 'storage/noesis/latest_radii.txt'
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(26,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(26,)
    else:
        centers = []
        for i in range(5):
            for j in range(6):
                if len(centers) < 26:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        c = np.array(centers, float)
        r = np.full(26, 0.08, float)
    r = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r.astype(float)
